def main():
    import sys
    s = sys.stdin.readline().strip()
    n = len(s)
    res = 0
    for i in range(n):
        ones = 0
        for j in range(i, n):
            if s[j] == '1':
                ones += 1
            length = j - i + 1
            if ones >= 1 and length % ones == 0:
                res += 1
    print(res)

main()
